#!/usr/bin/env python3
"""generate_golden.py — produce the layernorm_fused golden inputs/outputs.

Convention (polykernel): bf16 round-to-nearest-even inputs, fp32 accumulate,
bf16 output. The device kernel and this script apply the SAME formula
(one-pass E[x^2] - mean^2 variance, rsqrt-ish normalize), so the residual is
fp32 rounding order only.

Writes (committed):
  golden_inputs.npz   X (bf16 RNE), gamma (bf16 RNE), beta (bf16 RNE), eps
  golden_outputs.npz  Y (fp32, pre-bf16 cast — the comparison target)
  input.bin           self-describing binary consumed by layernorm_app
                      (NOT committed; regenerated by check_layernorm.py)

Run: python3 tests/fixtures/layernorm_fused/generate_golden.py
"""

import numpy as np
from ml_dtypes import bfloat16
from pathlib import Path

HERE = Path(__file__).resolve().parent
M, N = 1024, 128
EPS = np.float32(1.0e-5)


def main() -> None:
    rng = np.random.default_rng(42)
    x_f32 = rng.normal(0.0, 1.0, size=(M, N)).astype(np.float32)
    gamma = rng.uniform(0.5, 1.5, size=(N,)).astype(np.float32)
    beta = rng.normal(0.0, 0.25, size=(N,)).astype(np.float32)

    # bf16 RNE round the inputs the device will actually see
    x_bf16 = bfloat16(x_f32)
    g_bf16 = bfloat16(gamma)
    b_bf16 = bfloat16(beta)
    # device works on the bf16-rounded values re-expanded to fp32
    x32 = x_bf16.astype(np.float32)
    g32 = g_bf16.astype(np.float32)
    b32 = b_bf16.astype(np.float32)

    # same formula as the kernel: mean = sum/N, var = max(sum(x^2)/N - mean^2, 0)
    mean = x32.sum(axis=1, keepdims=True) / np.float32(N)
    ssq = (x32 * x32).sum(axis=1, keepdims=True) / np.float32(N)
    var = np.maximum(ssq - mean * mean, np.float32(0.0))
    inv = np.float32(1.0) / np.sqrt(var + EPS)
    y_f32 = (x32 - mean) * inv * g32[None, :] + b32[None, :]

    np.savez(
        HERE / "golden_inputs.npz",
        X=x_bf16.view(np.uint16).astype(np.uint16),
        gamma=g_bf16.view(np.uint16).astype(np.uint16),
        beta=b_bf16.view(np.uint16).astype(np.uint16),
        eps=EPS,
    )
    np.savez(HERE / "golden_outputs.npz", Y=y_f32)

    # self-describing binary input for layernorm_app (regenerated on demand)
    with (HERE / "input.bin").open("wb") as f:
        f.write(np.int32(M).tobytes())
        f.write(np.int32(N).tobytes())
        f.write(x_bf16.view(np.uint16).astype(np.uint16).tobytes())
        f.write(g_bf16.view(np.uint16).astype(np.uint16).tobytes())
        f.write(b_bf16.view(np.uint16).astype(np.uint16).tobytes())

    print(f"[PASS] generate_golden: {M}x{N} layernorm golden written to "
          f"{HERE.name}/ (inputs + outputs npz + input.bin)")


if __name__ == "__main__":
    main()
